mapper.sql:
c.deleted = 0
AND c.deleted_at IS NULL
AND c.status = 'PUBLISHED'
AND c.course_kind IN ('OFFICIAL', 'TRAVELER')

    AND c.course_kind = #{kind}


    AND EXISTS (
        SELECT 1 FROM course_countries membership
        WHERE membership.course_id = c.id AND membership.country_id = #{countryId}
    )


    AND EXISTS (
        SELECT 1 FROM course_theme_mappings mapping
        WHERE mapping.course_id = c.id AND mapping.theme_id = #{themeId}
    )
